public void teleportTowards(Entity target) {
        Vec3 vec3 = new Vec3(this.getX() - target.getX(), this.getY(0.5D) - target.getEyeY(), this.getZ() - target.getZ());
        vec3 = vec3.normalize();
        double d0 = 16.0D;
        double d1 = this.getX() + (this.random.nextDouble() - 0.5D) * 8.0D - vec3.x * 16.0D;
        double d2 = this.getY() + (double)(this.random.nextInt(16) - 8) - vec3.y * 16.0D;
        double d3 = this.getZ() + (this.random.nextDouble() - 0.5D) * 8.0D - vec3.z * 16.0D;
        this.teleportTo(d1, d2, d3);
    }

public void addAdditionalSaveData(CompoundTag p_36975_) {
        super.addAdditionalSaveData(p_36975_);
        p_36975_.putString("Particle", this.getParticle().writeToString());
        ItemStack itemstack = this.getItemRaw();
        if (!itemstack.isEmpty()) {
            p_36975_.put("Item", itemstack.save(new CompoundTag()));
        }
        p_36975_.putInt("Life", this.life);
        p_36975_.putInt("Cool", this.secondsCool);
    }

public void readAdditionalSaveData(CompoundTag p_36970_) {
        super.readAdditionalSaveData(p_36970_);
        if (p_36970_.contains("Particle", 8)) {
            try {
                this.setParticle(ParticleArgument.readParticle(new StringReader(p_36970_.getString("Particle")), BuiltInRegistries.PARTICLE_TYPE.asLookup()));
            } catch (CommandSyntaxException ignored) {
            }
        }
        ItemStack itemstack = ItemStack.of(p_36970_.getCompound("Item"));
        this.setItem(itemstack);
        if (p_36970_.contains("Life")){
            this.life = p_36970_.getInt("Life");
        }
        if (p_36970_.contains("Cool")){
            this.secondsCool = p_36970_.getInt("Cool");
        }
    }

protected void tickDeath() {
        ++this.deathTime;
        if (this.deathTime == 40) {
            if (this.getTrueOwner() != null && MobsConfig.BlackBeastHowlingSoul.get()){
                ItemStack itemStack = new ItemStack(ModItems.HOWLING_SOUL.get());
                HowlingSoul.setOwnerName(this.getTrueOwner(), itemStack);
                HowlingSoul.setSummon(this, itemStack);
                FlyingItem flyingItem = new FlyingItem(ModEntityType.FLYING_ITEM.get(), this.level, this.getX(), this.getY(), this.getZ());
                flyingItem.setOwner(this.getTrueOwner());
                flyingItem.setItem(itemStack);
                flyingItem.setParticle(ModParticleTypes.TOTEM_EFFECT.get());
                flyingItem.setSecondsCool(ItemConfig.ReviveSecondsCool.get());
                this.level.addFreshEntity(flyingItem);
            }
            this.remove(RemovalReason.KILLED);
            this.dropExperience();
        }
        if (this.level instanceof ServerLevel serverLevel){
            double d0 = this.random.nextGaussian() * 0.02D;
            double d1 = this.random.nextGaussian() * 0.02D;
            double d2 = this.random.nextGaussian() * 0.02D;
            serverLevel.sendParticles(ModParticleTypes.WRAITH.get(), this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), 0, d0, d1, d2, 0.5F);
            serverLevel.sendParticles(ModParticleTypes.WRAITH_BURST.get(), this.getRandomX(1.0D), this.getY(), this.getRandomZ(1.0D), 0, d0, d1, d2, 0.5F);
        }
        this.setYRot(this.deathRotation);
        this.setYBodyRot(this.deathRotation);
    }

private static void summon(Spell.Impact.Action.Summon def, List<Spell.Modifier> spellModifiers,
                               RegistryEntry<Spell> spellEntry, LivingEntity caster, ImpactContext context) {
        var world = caster.getWorld();
        if (!(world instanceof ServerWorld serverWorld)) return;

        // Fold in summon-targeting spell modifiers without mutating the shared Summon / SummonBehaviour
        // instances stored on the registered spell: counts and lifespan adds are accumulated into
        // locals, attribute scaling and behaviour are recomputed onto fresh copies only when needed.
        int spawnCount = def.spawn_count;
        int groupCount = def.group_count;
        int spawnTicksAdd = 0, activeSecondsAdd = 0, despawnTicksAdd = 0;
        var extraActions = new ArrayList<SummonBehaviour.Action.Entry>();
        var attributeScaling = def.attribute_scaling;
        for (var modifier : spellModifiers) {
            spawnCount += modifier.summon_spawn_count_add;
            groupCount += modifier.summon_group_count_add;
            var behaviourMod = modifier.summon_behaviour;
            if (behaviourMod != null) {
                extraActions.addAll(behaviourMod.actions_add);
                spawnTicksAdd += behaviourMod.lifespan.spawn_ticks_add;
                activeSecondsAdd += behaviourMod.lifespan.active_seconds_add;
                despawnTicksAdd += behaviourMod.lifespan.despawn_ticks_add;
            }
            if (modifier.summon_attribute_scaling != null) {
                attributeScaling = AttributeScaling.merged(attributeScaling, modifier.summon_attribute_scaling);
            }
        }
        spawnCount = Math.max(0, spawnCount);
        groupCount = Math.max(0, groupCount);
        var behaviour = (extraActions.isEmpty() && spawnTicksAdd == 0 && activeSecondsAdd == 0 && despawnTicksAdd == 0)
                ? def.behaviour
                : def.behaviour.withModifiers(extraActions, spawnTicksAdd, activeSecondsAdd, despawnTicksAdd);

        var type = Registries.ENTITY_TYPE.get(Identifier.of(def.entity_type_id));
        for (int g = 0; g < groupCount; g++) {
            // Next group slot, wrapping around the list (null when no group offset is configured).
            var groupPlacement = def.group_placements.isEmpty() ? null : def.group_placements.get(g % def.group_placements.size());
            int groupDelay = groupPlacement != null ? groupPlacement.delay_ticks : 0;
            Vec3d groupAnchor = null; // caster position + group offset; captured from the first entity

            for (int i = 0; i < spawnCount; i++) {
                var created = (Entity) type.create(world);
                if (!(created instanceof SpellSummoned summoned)) return;

                // Next per-entity slot, wrapping around the list (null when no slots are configured).
                var placement = def.placements.isEmpty() ? null : def.placements.get(i % def.placements.size());

                summoned.onSummonedBySpell(new SpellSummoned.Args(caster, spellEntry, behaviour, attributeScaling, context));

                // Compose placements: the group offset's resulting position seeds the per-entity
                // placement (both rotate the look-offset by the caster's yaw, so the formation keeps
                // a consistent caster-relative orientation across groups).
                var origin = caster.getPos();
                if (groupPlacement != null) {
                    EntityPlacements.applyEntityPlacement(created, caster, origin, groupPlacement);
                    origin = created.getPos();
                }
                if (i == 0) groupAnchor = origin; // the group's anchor (pre per-entity offset)
                EntityPlacements.applyEntityPlacement(created, caster, origin, placement);

                // applyEntityPlacement only sets entity yaw; sync head/body yaw so the initial pose matches.
                boolean appliedYaw = (groupPlacement != null && groupPlacement.apply_yaw)
                        || (placement != null && placement.apply_yaw);
                if (appliedYaw && created instanceof LivingEntity living) {
                    living.setHeadYaw(living.getYaw());
                    living.setBodyYaw(living.getYaw());
                }
                // Anti-clip: when a contributing placement opts into `line_of_sight`, pull a placed
                // position that is out of the caster's line of sight back to the nearest visible point.
                boolean checkLineOfSight = (placement != null && placement.line_of_sight)
                        || (groupPlacement != null && groupPlacement.line_of_sight);
                if (checkLineOfSight) {
                    var visible = nearestVisiblePosition(caster, created.getPos(), serverWorld);
                    created.setPosition(visible.x, visible.y, visible.z);
                }

                // Defer the world spawn by the combined group + per-entity delay (0 = spawn this tick).
                int entityDelay = placement != null ? placement.delay_ticks : 0;
                ((WorldScheduler) serverWorld).schedule(groupDelay + entityDelay, () -> serverWorld.spawnEntity(created));
            }

            // Group spawn FX + sound: one-shot at the group anchor, deferred by the group delay.
            if (groupAnchor != null && (def.group_spawn_fx != null || def.group_spawn_sound != null)) {
                var anchor = groupAnchor;
                var fx = def.group_spawn_fx;
                var sound = def.group_spawn_sound;
                ((WorldScheduler) serverWorld).schedule(groupDelay, () -> {
                    if (fx != null) emitSummonGroupFx(serverWorld, caster, anchor, fx);
                    if (sound != null) playSummonSound(serverWorld, anchor, sound);
                });
            }
        }
    }

private static void summon(Spell.Impact.Action.Summon def, List<Spell.Modifier> spellModifiers,
                               RegistryEntry<Spell> spellEntry, LivingEntity caster, ImpactContext context) {
        var world = caster.getWorld();
        if (!(world instanceof ServerWorld serverWorld)) return;

        // Fold in summon-targeting spell modifiers without mutating the shared Summon / SummonBehaviour
        // instances stored on the registered spell: counts and lifespan adds are accumulated into
        // locals, attribute scaling and behaviour are recomputed onto fresh copies only when needed.
        int spawnCount = def.spawn_count;
        int groupCount = def.group_count;
        int spawnTicksAdd = 0, activeSecondsAdd = 0, despawnTicksAdd = 0;
        var extraActions = new ArrayList<SummonBehaviour.Action.Entry>();
        var attributeScaling = def.attribute_scaling;
        for (var modifier : spellModifiers) {
            spawnCount += modifier.summon_spawn_count_add;
            groupCount += modifier.summon_group_count_add;
            var behaviourMod = modifier.summon_behaviour;
            if (behaviourMod != null) {
                extraActions.addAll(behaviourMod.actions_add);
                spawnTicksAdd += behaviourMod.lifespan.spawn_ticks_add;
                activeSecondsAdd += behaviourMod.lifespan.active_seconds_add;
                despawnTicksAdd += behaviourMod.lifespan.despawn_ticks_add;
            }
            if (modifier.summon_attribute_scaling != null) {
                attributeScaling = AttributeScaling.merged(attributeScaling, modifier.summon_attribute_scaling);
            }
        }
        spawnCount = Math.max(0, spawnCount);
        groupCount = Math.max(0, groupCount);
        var behaviour = (extraActions.isEmpty() && spawnTicksAdd == 0 && activeSecondsAdd == 0 && despawnTicksAdd == 0)
                ? def.behaviour
                : def.behaviour.withModifiers(extraActions, spawnTicksAdd, activeSecondsAdd, despawnTicksAdd);

        var type = Registries.ENTITY_TYPE.get(Identifier.of(def.entity_type_id));
        for (int g = 0; g < groupCount; g++) {
            // Next group slot, wrapping around the list (null when no group offset is configured).
            var groupPlacement = def.group_placements.isEmpty() ? null : def.group_placements.get(g % def.group_placements.size());
            int groupDelay = groupPlacement != null ? groupPlacement.delay_ticks : 0;
            Vec3d groupAnchor = null; // caster position + group offset; captured from the first entity

            for (int i = 0; i < spawnCount; i++) {
                var created = (Entity) type.create(world);
                if (!(created instanceof SpellSummoned summoned)) return;

                // Next per-entity slot, wrapping around the list (null when no slots are configured).
                var placement = def.placements.isEmpty() ? null : def.placements.get(i % def.placements.size());

                summoned.onSummonedBySpell(new SpellSummoned.Args(caster, spellEntry, behaviour, attributeScaling, context));

                // Compose placements: the group offset's resulting position seeds the per-entity
                // placement (both rotate the look-offset by the caster's yaw, so the formation keeps
                // a consistent caster-relative orientation across groups).
                var origin = caster.getPos();
                if (groupPlacement != null) {
                    EntityPlacements.applyEntityPlacement(created, caster, origin, groupPlacement);
                    origin = created.getPos();
                }
                if (i == 0) groupAnchor = origin; // the group's anchor (pre per-entity offset)
                EntityPlacements.applyEntityPlacement(created, caster, origin, placement);

                // applyEntityPlacement only sets entity yaw; sync head/body yaw so the initial pose matches.
                boolean appliedYaw = (groupPlacement != null && groupPlacement.apply_yaw)
                        || (placement != null && placement.apply_yaw);
                if (appliedYaw && created instanceof LivingEntity living) {
                    living.setHeadYaw(living.getYaw());
                    living.setBodyYaw(living.getYaw());
                }
                // Anti-clip: when a contributing placement opts into `line_of_sight`, pull a placed
                // position that is out of the caster's line of sight back to the nearest visible point.
                boolean checkLineOfSight = (placement != null && placement.line_of_sight)
                        || (groupPlacement != null && groupPlacement.line_of_sight);
                if (checkLineOfSight) {
                    var visible = nearestVisiblePosition(caster, created.getPos(), serverWorld);
                    created.setPosition(visible.x, visible.y, visible.z);
                }

                // Defer the world spawn by the combined group + per-entity delay (0 = spawn this tick).
                int entityDelay = placement != null ? placement.delay_ticks : 0;
                ((WorldScheduler) serverWorld).schedule(groupDelay + entityDelay, () -> serverWorld.spawnEntity(created));
            }

            // Group spawn FX + sound: one-shot at the group anchor, deferred by the group delay.
            if (groupAnchor != null && (def.group_spawn_fx != null || def.group_spawn_sound != null)) {
                var anchor = groupAnchor;
                var fx = def.group_spawn_fx;
                var sound = def.group_spawn_sound;
                ((WorldScheduler) serverWorld).schedule(groupDelay, () -> {
                    if (fx != null) emitSummonGroupFx(serverWorld, caster, anchor, fx);
                    if (sound != null) playSummonSound(serverWorld, anchor, sound);
                });
            }
        }
    }

private static void emitSummonGroupFx(ServerWorld world, LivingEntity caster, Vec3d anchor, Fx.Visuals fx) {
        var visuals = fx.resolved(Fx.Context.NONE);
        if (!visuals.particles.isEmpty()) {
            ParticleHelper.sendBatches(anchor, caster, visuals.particles);
        }
        ModelEffectHelper.spawn(world, anchor, caster.getYaw(), visuals.models);
    }

private static void playSummonSound(ServerWorld world, Vec3d pos, Sound sound) {
        var soundEvent = Registries.SOUND_EVENT.get(Identifier.of(sound.id()));
        if (soundEvent != null) {
            world.playSound(null, pos.x, pos.y, pos.z, soundEvent,
                    SoundCategory.PLAYERS, sound.volume(), sound.randomizedPitch());
        }
    }

default void schedule(int ticks, Runnable task) {
        if (ticks < 0) {
            task.run();
            return;
        }
        if (ticks == 0) {
            getImmediateTasks().add(task);
            return;
        }
        long executionTime = getSchedulerTime() + ticks;
        var list = getScheduledTasks().getOrDefault(executionTime, new ArrayList<>());
        list.add(task);
        getScheduledTasks().put(executionTime, list);
    }

default void updateScheduledTasks() {
        if (!getImmediateTasks().isEmpty()) {
            var copyTasks = new ArrayList<>(getImmediateTasks());
            getImmediateTasks().clear();
            for (Runnable task : copyTasks) {
                task.run();
            }
        }

        var taskQueue = getScheduledTasks();
        if (taskQueue.isEmpty()) {
            return;
        }
        var currentTime = getSchedulerTime();
        var currentTasks = taskQueue.get(currentTime);
        if (currentTasks != null) {
            for (Runnable task : currentTasks) {
                task.run();
            }
            taskQueue.remove(currentTime);
        }
    }

@Inject(method = "tick", at = @At("TAIL"))
    private void tick_TAIL_SpellEngine(BooleanSupplier shouldKeepTicking, CallbackInfo ci) {
        updateScheduledTasks();
    }

@Override
    public void serverTick() {
        long currentTick = mob.level.getGameTime();
        if (mob.getVehicle() != null) {
            if (mob.getVehicle().getUUID().equals(loadedTarget)) {
                setLeapTarget((LivingEntity) mob.getVehicle());
                loadedTarget = null;
            } else if (target == null && isAttackRiding()) {
                mob.stopRiding();
                stopAttackRiding();
            }
        }
        if (!isLeaping() && target != null && target.isAlive()) {
            mob.lookAt(target, 100, 10);
            if (mob.distanceToSqr(target) < JUMP_DISTANCE) {
                startLeap();
                if (mob.hasLeapAnimation()) {
                    ServerAnimationInfo animation = (ServerAnimationInfo) mob.getLeapStartAnimation();
                    jumpDelayTick = (long) (currentTick + animation.actionDelay);
                } else {
                    jumpDelayTick = currentTick + 2;
                }
                mob.setDeltaMovement(Vec3.ZERO);
            }
        }
        if (!isLeaping() && blockTarget != null) {
            if (mob.distanceToSqr(blockTarget) < JUMP_DISTANCE) {
                startLeap();
                if (mob.hasLeapAnimation()) {
                    ServerAnimationInfo animation = (ServerAnimationInfo) mob.getLeapStartAnimation();
                    jumpDelayTick = (long) (currentTick + animation.actionDelay);
                } else {
                    jumpDelayTick = currentTick + 2;
                }
                mob.setDeltaMovement(Vec3.ZERO);
            }
        }
        if (isLeaping()) {
            if (target == null && blockTarget == null) {
                stopLeap();
            }
            if (target != null && ((target.isVehicle() && mob.getVehicle() != target) || target.isDeadOrDying())) {
                if (jumpDelayTick != -1) {
                    blockTarget = target.position();
                }
                setAttackRiding(false);
                setLeapTarget(null);
            }
            if (currentTick == jumpDelayTick) {
                double y;
                Vec3 offset;
                if (target != null) {
                    y = Math.min(target.getY() + target.getBbHeight() - mob.getY(), 5);
                    offset = Util.directionVecTo(mob, target).normalize();
                    offset = offset.add(target.getDeltaMovement().x, 0, target.getDeltaMovement().z);
                } else if (blockTarget != null) {
                    y = Math.min(blockTarget.y - mob.getY(), 5);
                    offset = blockTarget.subtract(mob.position()).normalize();
                } else {
                    //Shouldn't really happen
                    y = 0;
                    offset = Vec3.ZERO;
                }
                mob.setDeltaMovement(offset.x, -0.027 * Math.pow(y, 2) + 0.262 * y + 0.183, offset.z);
                setLeapStarted(false);
                setLeapFlying(true);
                landingDelayTick = jumpDelayTick + 5;
                jumpDelayTick = -1;
            }
            if (mob.isOnGround() && landingDelayTick != -1 && landingDelayTick <= currentTick) {
                if (mob.hasLeapAnimation()) {
                    ServerAnimationInfo animation = (ServerAnimationInfo) mob.getLandAnimation();
                    landingEndTick = (long) (currentTick + animation.animation.animationLength);
                } else {
                    landingEndTick = currentTick + 2;
                }
                landingDelayTick = -1;
                setLeapFlying(false);
                setLanding(true);
            }
            if (landingEndTick != -1 && landingEndTick <= currentTick) {
                setLanding(false);
                setLeaping(false);
                landingEndTick = -1;
                setBlockLeapTarget(null);
                setLeapTarget(null);
            }
            if (isAttackRiding() && target != null) {
                if (mob.tickCount % 20 == 0) {
                    target.hurt(DamageSource.mobAttack(mob), (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE));
                    //target can be set to null during hurt
                }
                if (target != null && target.isDeadOrDying()) {
                    stopAttackRiding();
                }
            }
            if(!isLeapFlying() && !hasLeapStarted() && !isLanding() && !isAttackRiding()) {
                //failsafe
                setLeaping(false);
            }
            //Collision is handled in entity class
        }
    }

